#include <stdint.h>
#include <limits.h>
#include "sensorarrayAdsMath.h"
int64_t model_eval(int32_t exc,int32_t node,int32_t avss,uint32_t rref) { sensorarrayAdsResistanceConfig_t c={.referenceResistorOhms=rref,.pathOffsetMilliohms=0,.minimumOhms=1,.maximumOhms=100000000,.shortThresholdOhms=10,.openDenominatorUv=1000}; sensorarrayAdsResistanceResult_t r=sensorarrayAdsMathResistanceDivider(exc,node,avss,&c); return r.valid?r.resistanceMilliohms:INT64_MIN; }
int32_t model_split(int32_t span,unsigned index) { sensorarrayAdsRailInput_t i={.measuredRailUv=span,.nominalAvddToGroundUv=3300000,.nominalAvssToGroundUv=1800000,.ageFrames=0,.maximumAgeFrames=100,.valid=true}; sensorarrayAdsRailSplit_t r={0}; if(!sensorarrayAdsMathSplitRail(&i,&r))return INT32_MIN; return index==0?r.avddUv:index==1?r.avssUv:r.aincomUv; }
